<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import AccessLog from './AccessLog.vue'
import {hostModes} from './hostBilling'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,userId?:string}>()
const stats=ref<Row>({}),records=ref<Row[]>([]),users=ref<Row[]>([]),filter=ref(props.userId??''),error=ref(''),loading=ref(false),last=ref('')
const bytes=(n:any)=>{const v=Number(n??0);return v>=1073741824?(v/1073741824).toFixed(2)+' GiB':v>=1048576?(v/1048576).toFixed(1)+' MiB':v>=1024?(v/1024).toFixed(1)+' KiB':v+' B'}
const recordsOpen=ref(!!props.userId),recordsLoading=ref(false)
const resets:Record<string,string>={never:'不自动重置',daily:'每天',monthly:'每月 1 日',rolling_monthly:'按起点每月'}
const selected=computed(()=>users.value.find(u=>u.id===filter.value)),scoped=computed(()=>props.userId?users.value.find(u=>u.id===props.userId):undefined),allocated=computed(()=>Number(scoped.value?.quota_bytes??stats.value.allocated_bytes??0)),used=computed(()=>Number(scoped.value?.used_bytes??stats.value.used_bytes??0)),remaining=computed(()=>scoped.value?scoped.value.quota_bytes?Math.max(0,scoped.value.quota_bytes-scoped.value.used_bytes):null:Number(stats.value.remaining_bytes??0))
const date=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'不自动重置'
const chart=computed(()=>{const d=(props.userId?stats.value.user_daily:stats.value.daily)??[];const max=Math.max(1,...d.map((v:Row)=>Number(v.uplink)+Number(v.downlink)));return d.map((v:Row)=>({...v,height:Number(v.uplink)+Number(v.downlink)>0?Math.max(3,(Number(v.uplink)+Number(v.downlink))/max*100):0}))})
let alive=true,timer:ReturnType<typeof setTimeout>,sequence=0
async function load(){loading.value=true;const seq=++sequence;try{const [a,c]=await Promise.all([props.api('dashboard'+(props.userId?'?user_id='+props.userId:'')),props.api('proxy-users')]);if(!alive||seq!==sequence)return;stats.value=a;users.value=c;last.value=new Date().toLocaleTimeString();error.value=''}catch(e){if(alive&&seq===sequence)error.value=String(e)}finally{if(alive&&seq===sequence)loading.value=false}}
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden')await load();if(alive)schedule()},30000)}
onMounted(()=>{void load();schedule()});onUnmounted(()=>{alive=false;sequence++;clearTimeout(timer)})
</script>
<template><div class="traffic-workspace"><div class="traffic-toolbar"><p class="muted">{{last?'最近更新 '+last:'等待统计数据'}} · 上传 + 下载合计 · GiB = 1024³ 字节</p><button class="secondary" :disabled="loading" @click="load">刷新统计</button></div><p v-if="error" class="error" role="alert">{{error}}</p>
<div class="traffic-stats"><article><small>{{props.userId?'该用户今日流量':'今日入口流量'}}</small><strong>{{bytes(props.userId?stats.user_today_bytes:stats.today_bytes)}}</strong><span>{{props.userId?'北京时间自然日 · 用户身份计量':'上传 '+bytes(stats.today_uplink)+' / 下载 '+bytes(stats.today_downlink)}}</span></article><article><small>{{props.userId?'该用户本期已用':'全部用户本期已用'}}</small><strong>{{bytes(used)}}</strong><span>各用户自己的重置周期 · 不等于今日流量</span></article><article><small>{{props.userId?'该用户剩余额度':'有限配额剩余'}}</small><strong>{{remaining===null?'不限额':bytes(remaining)}}</strong><span>已分配 {{allocated?bytes(allocated):'不限额'}}{{props.userId?'':' · '+(stats.unlimited_users??0)+' 人不限额'}}</span></article><article><small>{{props.userId?'该用户累计已用':'近 60 秒活跃 / 总用户'}}</small><strong v-if="props.userId">{{bytes(scoped?.lifetime_bytes)}}</strong><strong v-else>{{stats.online_users??0}} <em>/ {{stats.users??0}}</em></strong><span>{{props.userId?'下次重置：'+date(scoped?.next_reset_at):(stats.active_users??0)+' 人当前可用 · '+(stats.limited_users??0)+' 人额度耗尽'}}</span></article></div><p class="muted traffic-scope">{{props.userId?'当前用户：'+(scoped?.name??'等待用户数据'):'全局统计 · '+(stats.online_hosts??0)+'/'+(stats.hosts??0)+' 主机在线 · '+(stats.running_inbounds??0)+'/'+(stats.enabled_inbounds??0)+' 个已启用入站运行'}}。入口流量按链路逐跳计量，个人账单独立汇总。有限余额逐用户计算，不扣除无限额度用户用量。</p>
<div class="traffic-overview"><section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">BANDWIDTH / LAST 14 DAYS</span><h2>流量趋势</h2></div><span class="status succeeded">{{stats.online_hosts??0}} / {{stats.hosts??0}} 主机在线</span></div><div v-if="chart.length" class="traffic-chart"><div v-for="d in chart" :key="d.day" class="chart-day" :title="d.day+' · '+bytes(Number(d.uplink)+Number(d.downlink))"><div class="bar-track"><i :style="{height:d.height+'%'}"></i></div><small>{{d.day?.slice(5)}}</small></div></div><div v-else class="console-empty">从本版本统计启用后开始累计，历史流量无法追溯。</div></section>
<section v-if="!props.userId" class="panel publish-card"><span class="eyebrow">NATIVE TELEMETRY</span><h2>采集与运行</h2><p><b>{{stats.running_inbounds??0}}</b> 个已应用的运行入站</p><div v-for="m in stats.telemetry??[]" :key="m.host_id+m.engine" class="meter-row"><span>{{m.host_name}}<small class="block-muted">{{m.engine}}</small></span><span :class="['status',m.fresh===true?'succeeded':'pending']">{{m.fresh===true?'采集中':'等待 / 不可用'}}</span></div><p class="muted">内核提供真实计数，约 10 秒上报。短时在途流量、进程异常退出可能造成少量误差。共享密钥协议单独统计入口流量。</p></section></div>
<section v-if="!props.userId&&stats.host_traffic?.length" class="panel publish-card"><span class="eyebrow">HOSTS / NETWORK ALLOWANCE</span><h2>主机套餐流量</h2><p class="muted">按系统网卡计量，包含代理之外的主机流量。已用按主机计费方式计算；断报显示最后采样，套餐历史已用请在主机中校准。</p><div class="table-scroll"><table><thead><tr><th>主机</th><th>本期已用 / 套餐</th><th>剩余</th><th>计量口径</th><th>采样与周期</th></tr></thead><tbody><tr v-for="h in stats.host_traffic" :key="h.host_id"><td>{{h.name}}</td><td>{{bytes(h.used_bytes)}} / {{h.quota_bytes?bytes(h.quota_bytes):'不限额'}}</td><td>{{h.quota_bytes?bytes(h.remaining_bytes):'不限额'}}</td><td>{{hostModes[h.mode]}}<small class="block-muted">↓ {{bytes(h.period_rx)}} / ↑ {{bytes(h.period_tx)}}</small></td><td><span :class="['status',h.fresh?'succeeded':'pending']">{{h.fresh?'最新采样':'等待 / 断报'}}</span><small class="block-muted">{{h.last_sample_at?date(h.last_sample_at):'需 Agent 0.18'}}{{h.quality==='gap'?' · 需核对':''}}</small><small v-if="h.next_reset_at" class="block-muted">重置 {{date(h.next_reset_at)}}</small></td></tr></tbody></table></div></section><section v-if="!props.userId" class="panel publish-card"><span class="eyebrow">INBOUNDS / TRANSFER</span><h2>各入口流量</h2><p class="muted">自启用本版统计后累计。链式代理每一跳分别计量；入口总量与用户账单分别汇总，不叠加收费。共享密钥入口也可在这里查看。</p><div class="table-scroll"><table><thead><tr><th>入口 / 主机</th><th>协议 / 内核</th><th>上传</th><th>下载</th><th>合计</th></tr></thead><tbody><tr v-for="i in stats.inbound_usage??[]" :key="i.id"><td>{{i.name}}<small class="block-muted">{{i.host_name}}</small></td><td>{{i.kind}}<small class="block-muted">{{i.engine}}</small></td><td>{{bytes(i.uplink)}}</td><td>{{bytes(i.downlink)}}</td><td>{{bytes(Number(i.uplink)+Number(i.downlink))}}</td></tr></tbody></table></div><p v-if="!stats.inbound_usage?.length" class="console-empty">尚未配置代理入口。</p></section>
<section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">USERS / QUOTAS</span><h2>用户流量与额度</h2></div></div><div class="table-scroll"><table><thead><tr><th>用户</th><th>本期已用 / 分配</th><th>剩余额度</th><th>重置周期</th><th>累计已用</th></tr></thead><tbody><tr v-for="u in (props.userId?users.filter(u=>u.id===props.userId):users)" :key="u.id"><td><button class="text-button" @click="filter=u.id;recordsOpen=true">{{u.name}}</button><small class="block-muted">{{u.limited?'额度耗尽':u.active?'有效':u.enabled?'已到期':'已停用'}}</small></td><td>{{bytes(u.used_bytes)}} / {{u.quota_bytes?bytes(u.quota_bytes):'不限'}}<progress v-if="u.quota_bytes" :value="u.used_bytes" :max="u.quota_bytes"></progress></td><td>{{u.quota_bytes?bytes(Math.max(0,u.quota_bytes-u.used_bytes)):'不限'}}</td><td>{{u.reset_strategy==='rolling_monthly'?'每月 '+(u.reset_day||new Date(u.reset_anchor_at).getDate())+' 日':resets[u.reset_strategy]??'不自动重置'}}<small v-if="u.next_reset_at" class="block-muted">下次 {{date(u.next_reset_at)}}</small></td><td>{{bytes(u.lifetime_bytes)}}<small class="block-muted">倍率 {{Number(u.multiplier_milli??1000)/1000}}× · {{({both:'双向',uplink:'仅上传',downlink:'仅下载',max:'累计取大'} as Record<string,string>)[u.billing_mode??'both']}}</small></td></tr></tbody></table></div><p v-if="!users.length" class="console-empty">添加用户并分配入站后，可设置流量额度与重置周期。</p></section>
<AccessLog :api="api" v-model:user-id="filter" v-model:expanded="recordsOpen" :users="users"/></div></template>
<style scoped>.traffic-scope{margin:0;font-size:12px;line-height:1.8}.traffic-workspace{display:grid;gap:22px}.traffic-toolbar{display:flex;justify-content:space-between;gap:20px;align-items:center}.traffic-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.traffic-stats article{border:1px solid var(--line);background:var(--panel);border-radius:14px;padding:23px}.traffic-stats small{color:var(--muted);font-size:12px}.traffic-stats strong{display:block;font-size:27px;margin:13px 0 10px;letter-spacing:-1px}.traffic-stats span{font-size:10px;color:var(--muted)}.traffic-stats em{font-size:15px;font-style:normal;color:var(--muted)}.traffic-overview{display:grid;grid-template-columns:1.5fr 1fr;gap:22px}.traffic-chart{height:170px;display:flex;gap:10px;align-items:flex-end;padding-top:15px}.chart-day{flex:1;min-width:0;text-align:center}.bar-track{height:125px;display:flex;align-items:flex-end;justify-content:center}.bar-track i{display:block;width:min(100%,34px);background:linear-gradient(var(--accent),color-mix(in srgb,var(--accent) 35%,transparent));border-radius:5px 5px 0 0}.chart-day small{font-size:9px;color:var(--muted);white-space:nowrap}.meter-row{display:flex;justify-content:space-between;align-items:center;padding:13px 0;border-top:1px solid var(--line);gap:15px;font-size:12px}progress{display:block;width:140px;height:5px;margin-top:8px;accent-color:var(--accent)}select{background:var(--input);color:var(--ink);padding:9px;border:1px solid var(--line);border-radius:7px;font-size:12px;margin-left:8px}@media(max-width:1100px){.traffic-stats{grid-template-columns:repeat(2,1fr)}.traffic-overview{grid-template-columns:1fr}}@media(max-width:650px){.traffic-stats{gap:10px}.traffic-stats article{padding:17px}.traffic-stats strong{font-size:22px}.traffic-toolbar{align-items:flex-start}.traffic-chart{gap:4px}.chart-day small{font-size:8px}}</style>
